async function run(api) {
  const status = await api.status();
  if (!status || status.remaining <= 0) return 'DENIED';
  await api.dispatch();
  return 'DISPATCHED';
}

async function run(api) {
  const status = await api.status();
  if (!status || status.remaining <= 0) return 'DENIED';
  const reservation = await api.reserve();
  if (!reservation || !reservation.allowed) return 'DENIED';
  await api.dispatch();
  return 'DISPATCHED';
}

